import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 value, address ownerCandidate) public {
        vm.assume(value > 0);
        vm.assume(ownerCandidate != address(0) && ownerCandidate != address(c) && ownerCandidate.code.length == 0);
        // Deploy a helper that succeeds on call so the fallback does not revert
        SuccessTarget target = new SuccessTarget();
        // We need to set the owner to an EOA we can observe; forge the owner by deploying through a prank
        vm.prank(ownerCandidate);
        c = new C();
        // Deal value to a caller
        address caller = makeAddr("caller");
        vm.deal(caller, value);
        uint256 ownerBalBefore = ownerCandidate.balance;
        vm.prank(caller);
        c.go{value: value}();
        uint256 ownerBalAfter = ownerCandidate.balance;
        // The correct contract forwards value to target, then sends the remaining balance (0) to owner.
        // The mutant skips the target call and sends the full value to owner.
        // Thus the owner's balance increase differs: in C it's 0, in M it's value.
        assertTrue(ownerBalAfter - ownerBalBefore == 0);
    }
}

