    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 ownerSeed) public {
        vm.assume(amount > 0);
        address owner = address(uint160(uint256(keccak256(abi.encode(ownerSeed)))));
        vm.assume(owner != address(0) && owner != address(c) && owner.code.length == 0);
        // Deploy an adversarial owner that reverts on receive
        RevertingOwner adversarialOwner = new RevertingOwner();
        // Set the adversarial owner as the contract's owner
        // The reference contract has `owner` set in constructor to msg.sender; we redeploy with prank
        vm.prank(address(adversarialOwner));
        c = new C();
        vm.deal(address(this), amount);
        // Note: `go` is payable and sends msg.value to target, then the remaining balance to owner
        // We call `go` with value = amount. The target 0xC8A... is an EOA, so the low-level call always succeeds.
        c.go{value: amount}();
        // Property: after call to go(), the contract's balance must be 0.
        assertEq(address(c).balance, 0, "Contract balance must be 0 after go()");
    }
}

