pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        // Deploy a helper that rejects ETH, simulating an adversarial owner that cannot receive Ether.
        NonPayableOwner ownerHelper = new NonPayableOwner();
        // Transfer ownership of c to the helper contract
        vm.prank(address(this));
        c.transferOwnership(address(ownerHelper));
        // Record owner helper balance before go
        uint256 ownerBalBefore = address(ownerHelper).balance;
        // Fund c with the fuzzed amount and call go
        vm.deal(address(c), amount);
        (bool success, ) = address(c).call(abi.encodeWithSignature("go()"));
        // The reference transfer reverts if owner cannot receive; our assertion must still hold for the reference.
        // For the buggy version, the call silently returns false, so go does not revert but owner balance unchanged.
        uint256 ownerBalAfter = address(ownerHelper).balance;
        // Property: if go succeeded, owner's balance must have increased by the full amount sent.
        // The reference will revert in the setup (transfer to non-payable owner) so trivially true;
        // the buggy version will succeed but owner balance will not increase, violating the property.
        assertTrue(!success || ownerBalAfter >= ownerBalBefore + amount);
    }
}

contract NonPayableOwner {
    // Fallback is non-payable, causing transfer to fail and call to succeed but return false.
    fallback() external { }
}

