pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Admissible domain: amount > 0 so there is ether to move
        vm.assume(amount > 0);
        // Deploy adversarial counterparty: re-entrant sender that calls back into c's fallback after receiving ETH
        ReentrantSender sender = new ReentrantSender(address(c));
        // Fund the sender with twice the amount (one for msg.value, one for reentrant callback)
        vm.deal(address(sender), amount * 2);
        // Record owner's pre-balance
        uint256 ownerPre = c.owner().balance;
        // Prank as the sender, call go() with the given amount
        vm.prank(address(sender));
        sender.initiate{value: amount}();
        // After the call, the owner's balance change should equal the msg.value sent by the sender
        uint256 ownerPost = c.owner().balance;
        assertTrue(ownerPost - ownerPre == amount);
    }
}

// Adversarial helper: receives ETH from C via go() and immediately sends back its balance to C via fallback
contract ReentrantSender {
    C public target;
    constructor(address _target) { target = C(_target); }
    function initiate() external payable {
        require(msg.value > 0, "need ether");
        target.go{value: msg.value}();
    }
    receive() external payable {
        // Re-entrant: send all received ether back to C's fallback
        if (address(this).balance > 0) {
            (bool ok, ) = address(target).call{value: address(this).balance}("");
            require(ok, "reenter failed");
        }
    }
}
